#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <mma.h>
#include <cooperative_groups.h>
#include <cstdio>
#include <cstring>
#include <cmath>
using namespace nvcuda; namespace cg=cooperative_groups;
__global__ void atomic_add(int* x,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)atomicAdd(x,1);}
__global__ void atomic_cas(int* x,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n){int old=*x,assumed;do{assumed=old;old=atomicCAS(x,assumed,assumed+1);}while(old!=assumed);}}
__global__ void scan_shuffle(const float* a,float* o,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;float v=i<n?a[i]:0;for(int d=1;d<32;d*=2){float t=__shfl_up_sync(0xffffffff,v,d);if((threadIdx.x&31)>=d)v+=t;}if((threadIdx.x&31)==31)atomicAdd(o,v);}
__global__ void scan_shared(const float* a,float* o,int n){__shared__ float s[256];int i=blockIdx.x*blockDim.x+threadIdx.x;s[threadIdx.x]=i<n?a[i]:0;__syncthreads();for(int d=1;d<256;d*=2){float t=threadIdx.x>=d?s[threadIdx.x-d]:0;__syncthreads();s[threadIdx.x]+=t;__syncthreads();}if(threadIdx.x==255)atomicAdd(o,s[255]);}
__global__ void coop_reduce(const float* a,float* o,int n){int i=blockIdx.x*blockDim.x+threadIdx.x;auto block=cg::this_thread_block();auto tile=cg::tiled_partition<32>(block);float s=i<n?a[i]:0;for(int d=16;d;d/=2)s+=tile.shfl_down(s,d);if(tile.thread_rank()==0)atomicAdd(o,s);}
__global__ void fill_f(float* a,int n,float v){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<n)a[i]=v;}
__global__ void gemm_fp32(const float*a,const float*b,float*c,int n){int x=blockIdx.x*16+threadIdx.x,y=blockIdx.y*16+threadIdx.y;if(x<n&&y<n){float s=0;for(int k=0;k<n;k++)s+=a[y*n+k]*b[k*n+x];c[y*n+x]=s;}}
__global__ void gemm_fp16(const half*a,const half*b,float*c,int n){int x=blockIdx.x*16+threadIdx.x,y=blockIdx.y*16+threadIdx.y;if(x<n&&y<n){float s=0;for(int k=0;k<n;k++)s+=__half2float(a[y*n+k])*__half2float(b[k*n+x]);c[y*n+x]=s;}}
__global__ void gemm_wmma_fp16(const half*a,const half*b,float*c,int n){int r=blockIdx.y*16,col=blockIdx.x*16;wmma::fragment<wmma::matrix_a,16,16,16,half,wmma::row_major> af;wmma::fragment<wmma::matrix_b,16,16,16,half,wmma::row_major> bf;wmma::fragment<wmma::accumulator,16,16,16,float> cf;wmma::fill_fragment(cf,0);for(int k=0;k<n;k+=16){wmma::load_matrix_sync(af,a+r*n+k,n);wmma::load_matrix_sync(bf,b+k*n+col,n);wmma::mma_sync(cf,af,bf,cf);}wmma::store_matrix_sync(c+r*n+col,cf,n,wmma::mem_row_major);}
__global__ void gemm_tf32(const float*a,const float*b,float*c,int n){int x=blockIdx.x*16+threadIdx.x,y=blockIdx.y*16+threadIdx.y;if(x<n&&y<n){float s=0;for(int k=0;k<n;k++)s+=a[y*n+k]*b[k*n+x];c[y*n+x]=s;}}
__global__ void gemm_wmma_tf32(const float*a,const float*b,float*c,int n){int r=blockIdx.y*16,col=blockIdx.x*16;wmma::fragment<wmma::matrix_a,16,16,8,wmma::precision::tf32,wmma::row_major> af;wmma::fragment<wmma::matrix_b,16,16,8,wmma::precision::tf32,wmma::row_major> bf;wmma::fragment<wmma::accumulator,16,16,8,float> cf;wmma::fill_fragment(cf,0);for(int k=0;k<n;k+=8){wmma::load_matrix_sync(af,a+r*n+k,n);wmma::load_matrix_sync(bf,b+k*n+col,n);wmma::mma_sync(cf,af,bf,cf);}wmma::store_matrix_sync(c+r*n+col,cf,n,wmma::mem_row_major);}
template<class F> float t(F f){cudaEvent_t s,e;cudaEventCreate(&s);cudaEventCreate(&e);for(int i=0;i<5;i++)f();cudaEventRecord(s);for(int i=0;i<30;i++)f();cudaEventRecord(e);cudaEventSynchronize(e);float ms;cudaEventElapsedTime(&ms,s,e);return ms/30;}
int check(const float*a,const float*b,int n){float *ha=new float[n],*hb=new float[n];cudaMemcpy(ha,a,n*4,cudaMemcpyDeviceToHost);cudaMemcpy(hb,b,n*4,cudaMemcpyDeviceToHost);int bad=0;for(int i=0;i<n;i++)if(fabs(ha[i]-hb[i])>1e-2)bad++;delete[]ha;delete[]hb;return bad;}
int main(int ac,char**av){if(ac<2)return 2;const char*m=av[1];
if(!strcmp(m,"atomic")){int n=1<<12,*a,*b;cudaMalloc(&a,4);cudaMalloc(&b,4);float p=t([&]{cudaMemset(a,0,4);atomic_add<<<(n+255)/256,256>>>(a,n);});float q=t([&]{cudaMemset(b,0,4);atomic_cas<<<(n+255)/256,256>>>(b,n);});int x,y;cudaMemcpy(&x,a,4,cudaMemcpyDeviceToHost);cudaMemcpy(&y,b,4,cudaMemcpyDeviceToHost);printf("atomic correctness=%s add_ms=%.4f cas_ms=%.4f speedup=%.3f\n",x==n&&y==n?"PASS":"FAIL",p,q,p/q);return 0;}
if(!strcmp(m,"shuffle")){int n=1<<12;float*a,*x,*y;cudaMalloc(&a,n*4);cudaMalloc(&x,4);cudaMalloc(&y,4);fill_f<<<(n+255)/256,256>>>(a,n,1);float p=t([&]{cudaMemset(x,0,4);scan_shuffle<<<(n+255)/256,256>>>(a,x,n);});float q=t([&]{cudaMemset(y,0,4);scan_shared<<<(n+255)/256,256>>>(a,y,n);});int z=0;int hx,hy;cudaMemcpy(&hx,x,4,cudaMemcpyDeviceToHost);cudaMemcpy(&hy,y,4,cudaMemcpyDeviceToHost);printf("shuffle correctness=%s shfl_ms=%.4f shared_ms=%.4f speedup=%.3f\n",hx==hy?"PASS":"FAIL",p,q,q/p);return 0;}
if(!strcmp(m,"fp16")){int n=512;half*a,*b;float*x,*y;cudaMalloc(&a,n*n*2);cudaMalloc(&b,n*n*2);cudaMalloc(&x,n*n*4);cudaMalloc(&y,n*n*4);cudaMemset(a,0,n*n*2);cudaMemset(b,0,n*n*2);dim3 z(16,16),g(n/16,n/16);float p=t([&]{gemm_fp16<<<g,z>>>(a,b,x,n);});float q=t([&]{gemm_wmma_fp16<<<g,32>>>(a,b,y,n);});printf("fp16-wmma correctness=%s mismatches=%d simt_ms=%.4f wmma_ms=%.4f speedup=%.3f\n",check(x,y,n*n)?"FAIL":"PASS",check(x,y,n*n),p,q,p/q);return 0;}
if(!strcmp(m,"tf32")){int n=512;float*a,*b,*x,*y;cudaMalloc(&a,n*n*4);cudaMalloc(&b,n*n*4);cudaMalloc(&x,n*n*4);cudaMalloc(&y,n*n*4);fill_f<<<(n*n+255)/256,256>>>(a,n*n,1);fill_f<<<(n*n+255)/256,256>>>(b,n*n,1);dim3 z(16,16),g(n/16,n/16);float p=t([&]{gemm_tf32<<<g,z>>>(a,b,x,n);});float q=t([&]{gemm_wmma_tf32<<<g,32>>>(a,b,y,n);});int bad=check(x,y,n*n);printf("tf32 correctness=%s mismatches=%d simt_ms=%.4f wmma_ms=%.4f speedup=%.3f\n",bad?"FAIL":"PASS",bad,p,q,p/q);return 0;}
if(!strcmp(m,"coop")){int n=1<<20;float*a,*x,*y;cudaMalloc(&a,n*4);cudaMalloc(&x,4);cudaMalloc(&y,4);fill_f<<<(n+255)/256,256>>>(a,n,1);float p=t([&]{cudaMemset(x,0,4);coop_reduce<<<(n+255)/256,256>>>(a,x,n);});float q=t([&]{cudaMemset(y,0,4);scan_shared<<<(n+255)/256,256>>>(a,y,n);});int hx,hy;cudaMemcpy(&hx,x,4,cudaMemcpyDeviceToHost);cudaMemcpy(&hy,y,4,cudaMemcpyDeviceToHost);printf("cooperative-reduction correctness=%s cooperative_ms=%.4f shared_ms=%.4f speedup=%.3f\n",hx==hy?"PASS":"FAIL",p,q,q/p);return 0;}
return 2;}
